import numpy as np

def solve_cubic(b):
    # Equation: c^3 - (503*b)c + (b^3 - 503) = 0
    A = 1
    B = 0
    C = -503 * b
    D = b**3 - 503

    # We are looking for integer roots c >= b
    # We can use numerical solvers and then check integers near the roots, 
    # or iterate since we have a strong bound on c.

    # For large b, c must be around sqrt(503*b).
    # Let's set a safe upper limit for iteration, say 1000, but rely on b^3-503/b if possible.
    # Since c must divide b^3 - 503, we only need to check divisors d of b^3 - 503 
    # such that d >= b.

    constant_term = b**3 - 503
    if constant_term == 0:
        return []

    potential_c = []

    # Iterate through divisors of the constant term
    # We only need to check positive divisors since c >= b >= 2.
    divisors = []
    for i in range(1, int(np.sqrt(abs(constant_term))) + 1):
        if constant_term % i == 0:
            divisors.append(i)
            if i*i != abs(constant_term):
                divisors.append(abs(constant_term) // i)

    # Filter for divisors c >= b
    for c_candidate in divisors:
        if c_candidate >= b:
            # Check if c_candidate is a root
            if c_candidate**3 - (503 * b) * c_candidate + (b**3 - 503) == 0:
                potential_c.append(c_candidate)

    return potential_c

solutions = {}
for b in range(2, 11):
    solutions[b] = solve_cubic(b)

print("Solutions found for b=2 to b=10:")
